//! Tasks T-1, T-3a and T-3c: header, framing and structural walk over every fixture (all fixture files, rules file
//! v3.5).
//!
//! Expected values are in `data/walk_expected.tsv`, generated by `data/gen_walk_expected.py` from the
//! Analyst's tools (`docs/formats/tools/exp_parse.py`, `intro_list.py`; header fields as printed by
//! `header_fields.py`; totals as printed by `corpus_counts.py` and `check_all.py`) run on (T-3d) over the
//! fixture files of the three fixture folders. The numbers of the plan (rules file v3.5 "Changes in session 10",
//! `implementation-plan.md` top) stand once in `common::TOTALS` / `common::FOLDER_TOTALS`.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::panic
)]

use std::collections::BTreeSet;
use std::io::Cursor;
use std::path::{Path, PathBuf};

use oradmp_core::exp::header::{read_header, Mode};
use oradmp_core::exp::intro::{IntroList, MatchKind};
use oradmp_core::exp::items::{walk, walk_path, ItemKind, WalkEnd, WalkOptions, WalkReport};
use oradmp_core::io::{ByteStream, DEFAULT_BUFFER};
use oradmp_core::{ErrorCode, WarningCode};

mod common;
use common::{FOLDER_TOTALS, TOTALS};

// ---------------------------------------------------------------------------------------------
// the expected table
// ---------------------------------------------------------------------------------------------

struct Row {
    file: String,
    size: u64,
    client_b1: u16,
    client_again: u16,
    db: u16,
    national: u16,
    reclen: u64,
    direct_flag: bool,
    mode: String,
    version: String,
    user: String,
    first_item: u64,
    sections: usize,
    parts: usize,
    rows: u64,
    fields: u64,
    nulls: u64,
    lines: u64,
    entries: Vec<[u64; 3]>,
    empty_direct: u64,
    empty_conv: u64,
    part_rows: Vec<u64>,
    lob_sections: usize,
    lob_rows: u64,
    lob_values: u64,
    lob_short: u64,
    lob_empty: u64,
    lob_long: u64,
    lob_bytes: u64,
}

fn triple(s: &str) -> [u64; 3] {
    let v: Vec<u64> = s.split('/').map(|x| x.parse().unwrap()).collect();
    [v[0], v[1], v[2]]
}

fn load_rows() -> Vec<Row> {
    let text = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/walk_expected.tsv"),
    )
    .unwrap();
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let head: Vec<&str> = lines.next().unwrap().split('\t').collect();
    lines
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            let g = |name: &str| f[head.iter().position(|h| *h == name).unwrap()];
            let n = |name: &str| -> u64 { g(name).parse().unwrap() };
            Row {
                file: g("file").to_string(),
                size: n("size"),
                client_b1: g("client_b1").parse().unwrap(),
                client_again: g("client_again").parse().unwrap(),
                db: g("db").parse().unwrap(),
                national: g("national").parse().unwrap(),
                reclen: n("reclen"),
                direct_flag: g("direct_flag") == "1",
                mode: g("mode").to_string(),
                version: g("version").to_string(),
                user: g("user").to_string(),
                first_item: n("first_item"),
                sections: g("sections").parse().unwrap(),
                parts: g("parts").parse().unwrap(),
                rows: n("rows"),
                fields: n("fields"),
                nulls: n("nulls"),
                lines: n("lines"),
                entries: (0..8).map(|i| triple(g(&format!("e{i}")))).collect(),
                empty_direct: n("empty_direct"),
                empty_conv: n("empty_conv"),
                part_rows: g("part_rows")
                    .split(',')
                    .map(|x| x.parse().unwrap())
                    .collect(),
                lob_sections: g("lob_sections").parse().unwrap(),
                lob_rows: n("lob_rows"),
                lob_values: n("lob_values"),
                lob_short: n("lob_short"),
                lob_empty: n("lob_empty"),
                lob_long: n("lob_long"),
                lob_bytes: n("lob_bytes"),
            }
        })
        .collect()
}

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../corpus/fixtures")
}

fn path_of(row: &Row) -> PathBuf {
    fixtures().join(&row.file)
}

fn read(row: &Row) -> Vec<u8> {
    std::fs::read(path_of(row)).unwrap()
}

fn folder(row: &Row) -> &str {
    row.file.split('/').next().unwrap()
}

fn walk_file(row: &Row, options: &WalkOptions) -> WalkReport {
    walk_path(&path_of(row), options).unwrap_or_else(|e| panic!("{}: {e}", row.file))
}

fn walk_bytes(bytes: Vec<u8>) -> oradmp_core::Result<WalkReport> {
    walk(Cursor::new(bytes), &WalkOptions::default())
}

fn per_entry(report: &WalkReport) -> Vec<[u64; 3]> {
    report
        .item_counts
        .per_entry
        .iter()
        .map(|e| [e.plain, e.marked, e.unmarked])
        .collect()
}

// ---------------------------------------------------------------------------------------------
// the table itself: it must cover every fixture and agree with the plan
// ---------------------------------------------------------------------------------------------

#[test]
fn table_covers_every_exp_fixture() {
    let rows = load_rows();
    let mut on_disk = BTreeSet::new();
    for d in ["18c", "11g", "11g-cp1251"] {
        for e in std::fs::read_dir(fixtures().join(d)).unwrap() {
            let name = e.unwrap().file_name().into_string().unwrap();
            if name.contains("_exp_") && name.ends_with(".dmp") {
                on_disk.insert(format!("{d}/{name}"));
            }
        }
    }
    let in_table: BTreeSet<String> = rows.iter().map(|r| r.file.clone()).collect();
    assert_eq!(
        on_disk, in_table,
        "every *_exp_*.dmp must have a line in walk_expected.tsv (T-3c: no file is left out)"
    );
    // the counts are compared with the Analyst's totals in one place: the plan-numbers test below
    assert_eq!(rows.len(), on_disk.len(), "one line per file");
}

/// The one place where the Analyst's totals meet the TSV (T-3d): `common::TOTALS` and `common::FOLDER_TOTALS`
/// (rules v3.5 "Changes in session 10": `corpus_counts.py` TOTAL of that version (`common::TOTALS` holds the current count), `problems 0`; `rowlen_stats.py`,
/// `num_decode.py` step 3) against `walk_expected.tsv`, `walk_parts.tsv` and `value_parts.tsv`. Per list
/// entry (plain, marked, unmarked): ` MODIFY DEFAULT` 30, `ANALSTATS ` 180 + 342, `COMMENT ON ` 134,
/// `CALTER TABLE` 51, `PROCACTION` 12, `CREATE FORMAT71 PROCEDURE ` 12, `CREATE FORMAT92TRIG ` 10,
/// `CREATE VIEW ` 12 (unmarked): 344 plain, 427 marked, 12 unmarked = 783 = `text_fields` (the entry numbers
/// are those `tools/intro_list.py` gives per file, summed by the generator; the sum is the Analyst's).
#[test]
fn tool_table_reproduces_the_plan_numbers_for_the_exp_files() {
    let rows = load_rows();
    for t in &FOLDER_TOTALS {
        let sel: Vec<&Row> = rows.iter().filter(|r| folder(r) == t.folder).collect();
        assert_eq!(sel.len(), t.files, "{} files", t.folder);
        assert_eq!(
            sel.iter().map(|r| r.sections).sum::<usize>(),
            t.sections,
            "{}",
            t.folder
        );
        assert_eq!(
            sel.iter().map(|r| r.parts).sum::<usize>(),
            t.parts,
            "{} parts",
            t.folder
        );
        assert_eq!(
            sel.iter().map(|r| r.rows).sum::<u64>(),
            t.rows,
            "{} rows",
            t.folder
        );
        assert_eq!(
            sel.iter().map(|r| r.fields).sum::<u64>(),
            t.fields,
            "{} fields",
            t.folder
        );
        assert_eq!(
            sel.iter().map(|r| r.nulls).sum::<u64>(),
            t.nulls,
            "{} nulls",
            t.folder
        );
        assert_eq!(
            sel.iter().map(|r| r.lob_sections).sum::<usize>(),
            t.lob_sections,
            "{} LOB sections",
            t.folder
        );
        let text_fields: u64 = sel
            .iter()
            .flat_map(|r| r.entries.iter())
            .map(|e| e.iter().sum::<u64>())
            .sum();
        assert_eq!(text_fields, t.text_fields, "{} text fields", t.folder);
    }
    assert_eq!(rows.len(), TOTALS.files);
    // rows of LOB tables: part of the rows of the file, and present exactly where a LOB table is
    for r in &rows {
        assert!(r.lob_rows <= r.rows, "{}", r.file);
        assert_eq!(r.lob_rows > 0, r.lob_sections > 0, "{}", r.file);
    }
    assert_eq!(
        rows.iter().map(|r| r.sections).sum::<usize>(),
        TOTALS.sections
    );
    assert_eq!(rows.iter().map(|r| r.parts).sum::<usize>(), TOTALS.parts);
    assert_eq!(rows.iter().map(|r| r.rows).sum::<u64>(), TOTALS.rows);
    assert_eq!(rows.iter().map(|r| r.fields).sum::<u64>(), TOTALS.fields);
    assert_eq!(rows.iter().map(|r| r.nulls).sum::<u64>(), TOTALS.nulls);
    assert_eq!(
        rows.iter().map(|r| r.empty_conv).sum::<u64>(),
        TOTALS.empty_conv
    );
    assert_eq!(
        rows.iter().map(|r| r.empty_direct).sum::<u64>(),
        TOTALS.empty_direct
    );
    assert_eq!(
        rows.iter().map(|r| r.lob_sections).sum::<usize>(),
        TOTALS.lob_sections
    );
    assert_eq!(
        rows.iter().map(|r| r.lob_values).sum::<u64>(),
        TOTALS.lob_values
    );
    assert_eq!(
        rows.iter().map(|r| r.lob_short).sum::<u64>(),
        TOTALS.lob_short
    );
    assert_eq!(
        rows.iter().map(|r| r.lob_long).sum::<u64>(),
        TOTALS.lob_long
    );
    assert_eq!(
        rows.iter().map(|r| r.lob_short + r.lob_long).sum::<u64>(),
        TOTALS.lob_values
    );
    let mut per = vec![[0u64; 3]; 8];
    for r in &rows {
        for (i, e) in r.entries.iter().enumerate() {
            for j in 0..3 {
                per[i][j] += e[j];
            }
        }
    }
    // entry order of the list: MODIFY DEFAULT, ANALSTATS, COMMENT ON, CALTER TABLE, PROCACTION, FORMAT71,
    // FORMAT92TRIG, CREATE VIEW (plain, marked, unmarked)
    assert_eq!(
        per,
        vec![
            [30, 0, 0],
            [180, 342, 0],
            [134, 0, 0],
            [0, 51, 0],
            [0, 12, 0],
            [0, 12, 0],
            [0, 10, 0],
            [0, 0, 12]
        ]
    );
    assert_eq!(
        per.iter().flatten().sum::<u64>(),
        TOTALS.text_fields,
        "text fields of all list entries"
    );
    // the other two golden files of the walker and of the values
    let lines = |name: &str| -> usize {
        std::fs::read_to_string(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("tests/data")
                .join(name),
        )
        .unwrap()
        .lines()
        .filter(|l| !l.starts_with('#'))
        .count()
            - 1
    };
    assert_eq!(lines("walk_parts.tsv"), TOTALS.parts);
    assert_eq!(lines("value_parts.tsv"), TOTALS.parts);
    let number_fields: u64 = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/value_parts.tsv"),
    )
    .unwrap()
    .lines()
    .filter(|l| !l.starts_with('#') && !l.starts_with("file\t"))
    .map(|l| l.split('\t').nth(5).unwrap().parse::<u64>().unwrap())
    .sum();
    assert_eq!(number_fields, TOTALS.number_fields);
    assert_eq!(
        lines("lob_expected.tsv"),
        rows.iter().map(|r| r.lob_sections).sum::<usize>(),
        "one lob_expected.tsv line per binary part of a LOB table"
    );
}

// ---------------------------------------------------------------------------------------------
// (a) header fields of all files
// ---------------------------------------------------------------------------------------------

#[test]
fn a_header_fields_of_every_file_equal_the_tool_table() {
    for row in load_rows() {
        let mut s =
            ByteStream::new(std::fs::File::open(path_of(&row)).unwrap(), DEFAULT_BUFFER).unwrap();
        let (h, warnings) = read_header(&mut s).unwrap_or_else(|e| panic!("{}: {e}", row.file));
        assert_eq!(h.client_charset, row.client_b1, "{}", row.file);
        assert_eq!(h.client_charset_again, row.client_again, "{}", row.file);
        assert_eq!(h.db_charset, row.db, "{}", row.file);
        assert_eq!(h.national_charset, row.national, "{}", row.file);
        assert_eq!(h.record_length, row.reclen, "{}", row.file);
        assert_eq!(h.direct_flag, row.direct_flag, "{}", row.file);
        assert_eq!(h.file_size, row.size, "{}", row.file);
        assert_eq!(h.first_item_offset, row.first_item, "{}", row.file);
        assert_eq!(h.version, row.version.as_bytes(), "{}", row.file);
        assert_eq!(
            [b"U".as_slice(), &h.user].concat(),
            row.user.as_bytes(),
            "{}",
            row.file
        );
        let mode = match &h.mode {
            Mode::Tables => "RTABLES".to_string(),
            Mode::Users => "RUSERS".to_string(),
            Mode::Other(o) => format!("R{}", String::from_utf8_lossy(o)),
        };
        assert_eq!(mode, row.mode, "{}", row.file);
        assert!(warnings.is_empty(), "{}: {warnings:?}", row.file);
    }
}

// ---------------------------------------------------------------------------------------------
// (b) the walk
// ---------------------------------------------------------------------------------------------

#[test]
fn b_walk_ends_at_the_second_exit_with_the_numbers_of_the_tool_and_no_file_stops() {
    let mut walked = 0;
    let (mut sections, mut parts, mut nrows, mut fields, mut nulls) =
        (0usize, 0usize, 0u64, 0u64, 0u64);
    let (mut text_fields, mut ec, mut ed) = (0u64, 0u64, 0u64);
    for row in load_rows().iter() {
        let report = walk_file(row, &WalkOptions::default());
        assert!(matches!(report.end, WalkEnd::Complete), "{}", row.file);
        assert!(
            report.warnings.is_empty(),
            "{}: {:?}",
            row.file,
            report.warnings
        );
        assert_eq!(report.sections.len(), row.sections, "{} sections", row.file);
        assert_eq!(report.parts().count(), row.parts, "{} parts", row.file);
        assert_eq!(
            report.parts().map(|p| p.rows.rows).collect::<Vec<_>>(),
            row.part_rows,
            "{} rows per part",
            row.file
        );
        assert_eq!(report.item_counts.lines, row.lines, "{} lines", row.file);
        assert_eq!(
            per_entry(&report),
            row.entries,
            "{} fields per entry",
            row.file
        );
        assert_eq!(report.item_counts.g1_fields, 0, "{}", row.file);
        assert_eq!(
            report.empty_tables(),
            (row.empty_direct, row.empty_conv),
            "{} empty tables",
            row.file
        );
        assert!(
            report.sections.iter().all(|s| !s.parts.is_empty()),
            "{}: every section has an INSERT INTO",
            row.file
        );
        let lob = report.lob_totals();
        assert_eq!(
            (lob.values, lob.short, lob.empty, lob.long, lob.stored_bytes),
            (
                row.lob_values,
                row.lob_short,
                row.lob_empty,
                row.lob_long,
                row.lob_bytes
            ),
            "{} LOB values",
            row.file
        );
        sections += report.sections.len();
        parts += report.parts().count();
        nrows += report.parts().map(|p| p.rows.rows).sum::<u64>();
        fields += report.parts().map(|p| p.rows.fields).sum::<u64>();
        nulls += report.parts().map(|p| p.rows.nulls).sum::<u64>();
        text_fields += report.item_counts.fields();
        let (d, c) = report.empty_tables();
        ed += d;
        ec += c;
        assert_eq!(
            report.parts().map(|p| p.rows.fields).sum::<u64>(),
            row.fields,
            "{} fields",
            row.file
        );
        assert_eq!(
            report.parts().map(|p| p.rows.nulls).sum::<u64>(),
            row.nulls,
            "{} nulls",
            row.file
        );
        // E4: the walk ends behind the second EXIT; only zero fill follows.
        let end = report.end_offset.unwrap();
        let bytes = read(row);
        assert!(
            bytes[usize::try_from(end).unwrap()..]
                .iter()
                .all(|&b| b == 0),
            "{}",
            row.file
        );
        assert_eq!(
            &bytes[usize::try_from(end).unwrap() - 10..usize::try_from(end).unwrap()],
            b"EXIT\nEXIT\n"
        );
        walked += 1;
    }
    // The plan numbers, from the walker itself (common::TOTALS: rules file v3.5, tools/corpus_counts.py).
    assert_eq!(walked, TOTALS.files);
    assert_eq!((sections, parts), (TOTALS.sections, TOTALS.parts));
    assert_eq!(
        (nrows, fields, nulls),
        (TOTALS.rows, TOTALS.fields, TOTALS.nulls)
    );
    assert_eq!(text_fields, TOTALS.text_fields);
    assert_eq!((ec, ed), (TOTALS.empty_conv, TOTALS.empty_direct));
}

#[test]
fn b_rows_equal_the_logs_of_a_few_tables() {
    // Row counts of the tool (exp_parse via check_all.py "name:rows" per table, all `ok` against the truth):
    // ddl_exp_18c T_PARENT 2, T_DDL 3; multi_types T_NUM 33, T_DATE 11, T_TS 6, T_TEXT 10;
    // multi_empty T_FRAME 7, T_EMPTY 0, T_LEN 22; stat: see below.
    let rows = load_rows();
    let find = |name: &str| rows.iter().find(|r| r.file.ends_with(name)).unwrap();
    let counts = |name: &str| -> Vec<u64> {
        walk_file(find(name), &WalkOptions::default())
            .sections
            .iter()
            .map(|s| s.parts[0].rows.rows)
            .collect()
    };
    assert_eq!(counts("ddl_exp_18c.dmp"), [2, 3]);
    assert_eq!(counts("multi_types_exp_direct_11g.dmp"), [33, 11, 6, 10]);
    assert_eq!(counts("multi_empty_exp_direct_18c.dmp"), [7, 0, 22]);
    assert_eq!(counts("multi_empty_exp_direct_11g.dmp"), [7, 0, 22]);
}

#[test]
fn b_a_tiny_buffer_gives_the_same_report() {
    // Fields, lengths and `ff ff` continue across buffer refills and across multiples of R [R5, I7]: the
    // 64-byte buffer crosses a refill in every few fields.
    for name in [
        "t_bn1_exp_18c.dmp",
        "t_bn3_exp_direct_11g.dmp",
        "t_probe6_exp_11g.dmp",
        "stat_exp_18c.dmp",
        "own_exp_direct_11g.dmp",
        "ru_tbl_exp_cp1251_11g.dmp",
        "t_wide_exp_18c.dmp",
        "lob_exp_18c.dmp",
        "lob_exp_direct_11g.dmp",
        "part_exp_direct_18c.dmp",
        "long_exp_11g.dmp",
    ] {
        let rows = load_rows();
        let row = rows.iter().find(|r| r.file.ends_with(name)).unwrap();
        let big = WalkOptions {
            record_items: true,
            ..WalkOptions::default()
        };
        let small = WalkOptions {
            record_items: true,
            buffer_bytes: 64,
            ..WalkOptions::default()
        };
        let a = walk_file(row, &big);
        let b = walk_file(row, &small);
        assert_eq!(a.sections, b.sections, "{name}");
        assert_eq!(a.items, b.items, "{name}");
        assert_eq!(a.item_counts, b.item_counts, "{name}");
        assert_eq!(a.end_offset, b.end_offset, "{name}");
        assert_eq!(a.warnings, b.warnings, "{name}");
    }
}

// ---------------------------------------------------------------------------------------------
// (c) with an empty list K the same items are read through G1
// ---------------------------------------------------------------------------------------------

#[test]
fn c_empty_list_k_reads_the_same_items_through_g1() {
    let with_list = WalkOptions {
        record_items: true,
        ..WalkOptions::default()
    };
    let without = WalkOptions {
        record_items: true,
        intro_list: Some(IntroList::empty()),
        ..WalkOptions::default()
    };
    for row in load_rows() {
        let a = walk_file(&row, &with_list);
        let b = walk_file(&row, &without);
        assert_eq!(a.items, b.items, "{}: same items", row.file);
        assert_eq!(a.sections, b.sections, "{}: same sections", row.file);
        assert_eq!(a.end_offset, b.end_offset, "{}", row.file);
        match (&a.end, &b.end) {
            (WalkEnd::Complete, WalkEnd::Complete) => {}
            (WalkEnd::Stopped(x), WalkEnd::Stopped(y)) => {
                assert_eq!((x.code, x.offset), (y.code, y.offset), "{}", row.file)
            }
            _ => panic!("{}: the two walks ended differently", row.file),
        }
        let fields = a.item_counts.fields();
        assert_eq!(b.item_counts.g1_fields, fields, "{}", row.file);
        assert_eq!(b.item_counts.fields(), fields, "{}", row.file);
        assert!(b.item_counts.per_entry.is_empty());
        // one warning per field, at the line that introduces it
        assert_eq!(b.warnings.len() as u64, fields, "{}", row.file);
        assert!(b
            .warnings
            .iter()
            .all(|w| w.code == WarningCode::UnknownIntro));
        let intro_offsets: Vec<u64> = b
            .items
            .windows(2)
            .filter(|w| matches!(w[1].kind, ItemKind::Field(_)))
            .map(|w| w[0].offset)
            .collect();
        let warned: Vec<u64> = b.warnings.iter().map(|w| w.offset.unwrap()).collect();
        assert_eq!(warned, intro_offsets, "{}", row.file);
        assert!(a.warnings.is_empty(), "{}", row.file);
    }
}

// ---------------------------------------------------------------------------------------------
// (d) the list file equals the block of the rules file, in all four fields (N-3, rules v3.2)
// ---------------------------------------------------------------------------------------------

/// `kind:length:forms:text` of the block in the rules file and of an entry of the data file.
type ListEntry = (String, usize, String, String);

#[test]
fn d_intro_list_file_equals_the_block_in_the_rules_file() {
    let rules = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/formats/exp_reader_rules.md"),
    )
    .unwrap();
    let mut block: Vec<ListEntry> = Vec::new();
    for line in rules.lines() {
        let Some(body) = line.strip_prefix("    ") else {
            continue;
        };
        let Some((kind, rest)) = body.split_once(':') else {
            continue;
        };
        if !["prefix", "exact", "suffix"].contains(&kind) {
            continue;
        }
        let (len, rest) = rest.split_once(':').unwrap();
        let (forms, text) = rest.split_once(':').unwrap();
        let len: usize = len.parse().unwrap();
        assert_eq!(
            text.len(),
            len,
            "the rules file states {len} bytes for {text:?}"
        );
        block.push((kind.to_string(), len, forms.to_string(), text.to_string()));
    }
    assert_eq!(block.len(), 8, "the block of the rules file has 8 entries");
    let list = IntroList::builtin().unwrap();
    let from_file: Vec<ListEntry> = list
        .entries()
        .iter()
        .map(|e| {
            let kind = match e.kind {
                MatchKind::Prefix => "prefix",
                MatchKind::Exact => "exact",
                MatchKind::Suffix => "suffix",
            };
            // forms in the order plain | marked | unmarked, as the block writes them
            let mut forms = Vec::new();
            if e.forms.plain {
                forms.push("plain");
            }
            if e.forms.marked {
                forms.push("marked");
            }
            if e.forms.unmarked {
                forms.push("unmarked");
            }
            (
                kind.to_string(),
                e.text.len(),
                forms.join("|"),
                String::from_utf8(e.text.clone()).unwrap(),
            )
        })
        .collect();
    assert_eq!(
        from_file, block,
        "kind, length, forms and text of every entry"
    );
    // the data file itself is the file that is embedded
    let raw = std::fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("data/exp_intro_lines.txt"),
    )
    .unwrap();
    assert_eq!(IntroList::parse(&raw).unwrap(), list);
    // a changed form is a difference (the test would not see it if forms were left out)
    let mut changed = block.clone();
    changed[1].2 = "plain".to_string();
    assert_ne!(from_file, changed);
}

