// The tests that expected the 7 CLOB files and the two `long_exp` files to stop (ADR-12 session 2) are replaced by
// `t3a_walker.rs` (rules v3.3: no file stops).

// ---------------------------------------------------------------------------------------------
// header and framing errors and warnings on patched copies (in memory)
// ---------------------------------------------------------------------------------------------

fn fixture_bytes(rel: &str) -> Vec<u8> {
    std::fs::read(fixtures().join(rel)).unwrap()
}

fn find_bytes(hay: &[u8], needle: &[u8]) -> usize {
    hay.windows(needle.len()).position(|w| w == needle).unwrap()
}

#[test]
fn h6_a_patched_first_item_gives_missing_metrics_line() {
    let rows = load_rows();
    for row in rows.iter().take(12) {
        let mut b = read(row);
        let at = usize::try_from(row.first_item).unwrap();
        assert_eq!(&b[at..at + 7], b"METRICS");
        b[at] = b'X';
        let e = walk_bytes(b).unwrap_err();
        assert_eq!(e.code, ErrorCode::MissingMetricsLine, "{}", row.file);
        assert_eq!(e.offset, Some(row.first_item), "{}", row.file);
    }
}

#[test]
fn h1_h3_not_an_exp_file() {
    let mut b = fixture_bytes("18c/t_num_exp_18c.dmp");
    b[0] = 0x1f;
    b[1] = 0x8b;
    let e = walk_bytes(b.clone()).unwrap_err();
    assert_eq!(e.code, ErrorCode::NotExpFile);
    assert!(e.message.contains("compressed"));
    b[0] = 0x04;
    assert_eq!(
        walk_bytes(b.clone()).unwrap_err().code,
        ErrorCode::NotExpFile
    );
    b[0] = 0x03;
    let at = find_bytes(&b, b"EXPORT:V");
    b[at] = b'X';
    assert_eq!(walk_bytes(b).unwrap_err().code, ErrorCode::NotExpFile);
    assert_eq!(
        walk_bytes(Vec::new()).unwrap_err().code,
        ErrorCode::NotExpFile
    );
}

#[test]
fn h5_bad_record_length() {
    let good = fixture_bytes("18c/t_num_exp_18c.dmp");
    // RECORDLENGTH text "8192" -> "0000", "81x2", and "819200" (the second record lies beyond the file)
    let at = find_bytes(&good, b"\n8192\n") + 1;
    for patch in [&b"0000"[..], b"81x2", b"819200"] {
        let mut b = good.clone();
        b.splice(at..at + 4, patch.iter().copied());
        let e = walk_bytes(b).unwrap_err();
        assert_eq!(e.code, ErrorCode::BadRecordLength, "{patch:?}");
        assert_eq!(e.offset, Some(at as u64));
    }
    // a RECORDLENGTH that is a number but not the real one: the first item is not where H6 says
    let mut b = good.clone();
    b[at..at + 4].copy_from_slice(b"8199");
    assert_eq!(
        walk_bytes(b).unwrap_err().code,
        ErrorCode::MissingMetricsLine
    );
}

#[test]
fn h3_h5_warnings_for_untested_version_and_record_length() {
    let good = fixture_bytes("18c/t_num_exp_18c.dmp");
    let report = walk_bytes(good.clone()).unwrap();
    assert!(report.warnings.is_empty());
    let mut b = good.clone();
    let at = find_bytes(&b, b"EXPORT:V18.00.00") + 10;
    b[at..at + 6].copy_from_slice(b"10.02.");
    let report = walk_bytes(b).unwrap();
    assert_eq!(report.warnings.len(), 1);
    assert_eq!(report.warnings[0].code, WarningCode::UntestedVersion);
    assert_eq!(report.warnings[0].offset, Some(3));
}

#[test]
fn e4_zero_fill_or_end_before_the_second_exit_is_truncated() {
    let rows = load_rows();
    let row = rows
        .iter()
        .find(|r| r.file == "18c/t_num_exp_18c.dmp")
        .unwrap();
    let end = usize::try_from(walk_file(row, &WalkOptions::default()).end_offset.unwrap()).unwrap();
    // cut inside the second EXIT line
    let mut b = read(row);
    b.truncate(end - 3);
    assert_eq!(walk_bytes(b).unwrap_err().code, ErrorCode::Truncated);
    // second EXIT replaced by zero fill
    let mut b = read(row);
    for x in &mut b[end - 5..end] {
        *x = 0;
    }
    let e = walk_bytes(b).unwrap_err();
    assert_eq!(
        (e.code, e.offset),
        (ErrorCode::Truncated, Some((end - 5) as u64))
    );
}

#[test]
fn e4_nonzero_bytes_after_the_second_exit_are_a_warning() {
    let rows = load_rows();
    let row = rows
        .iter()
        .find(|r| r.file == "18c/t_num_exp_18c.dmp")
        .unwrap();
    let mut b = read(row);
    let last = b.len() - 1;
    b[last] = 1;
    let report = walk_bytes(b).unwrap();
    assert_eq!(report.warnings.len(), 1);
    assert_eq!(report.warnings[0].code, WarningCode::Trailing);
    assert_eq!(report.warnings[0].offset, Some(last as u64));
}

#[test]
fn i2_a_line_beyond_max_line_bytes_is_framing_and_never_buffered_beyond_the_limit() {
    let rows = load_rows();
    let row = rows
        .iter()
        .find(|r| r.file == "18c/t_wide_exp_18c.dmp")
        .unwrap();
    let options = WalkOptions {
        max_line_bytes: 200,
        ..WalkOptions::default()
    };
    let e = walk_path(&path_of(row), &options).unwrap_err();
    assert_eq!(e.code, ErrorCode::Framing);
    // N-9 (T-14 g): exact. The first line above 200 bytes is the CREATE TABLE line of T_WIDE: offset 0x211c = 8476
    // is `create_off` of `tests/golden/exp_catalog.tsv` (Analyst's exp_parse.py); 2,606 is its length without the
    // LF (python over the fixture: the line from 8476 to the LF, whose SHA-256 equals the catalog's `ddl_sha256`).
    // The length is the bytes seen when the limit is crossed; the default buffer holds the whole line.
    assert_eq!((e.offset, e.length), (Some(8476), Some(2606)));
}

#[test]
fn damaged_files_never_panic() {
    // A cheap stand-in for the property tests of task T-14: truncation at many offsets, a byte flipped at
    // many offsets, on files of both paths, a small and the default buffer. Every outcome is Ok or a typed error.
    let rows = load_rows();
    for name in [
        "own_exp_direct_18c.dmp",
        "stat_exp_11g.dmp",
        "t_empty_exp_direct_11g.dmp",
        "ddl_exp_18c.dmp",
    ] {
        let row = rows.iter().find(|r| r.file.ends_with(name)).unwrap();
        let bytes = read(row);
        for buffer in [64, DEFAULT_BUFFER] {
            let options = WalkOptions {
                buffer_bytes: buffer,
                ..WalkOptions::default()
            };
            for cut in (0..bytes.len()).step_by(61) {
                let _ = walk(Cursor::new(bytes[..cut].to_vec()), &options);
            }
            for at in (0..bytes.len()).step_by(37) {
                let mut b = bytes.clone();
                b[at] ^= 0xff;
                let _ = walk(Cursor::new(b), &options);
            }
        }
    }
}
